// Gleiche Logik wie im Cockpit-Prototyp (lib/derive.ts, matchKriterien) –
// Standort zuerst, Entscheidung im Demo-Check 20.08.
// Erwartet: { objekt: { region, assetklasse, kaufpreisMio }, investoren: [{ id, regionen, assetklassen, ticketMinMio, ticketMaxMio }] }
const OBERMENGEN = ['Rhein-Main', 'Hessen', 'Deutschland', 'Deutschland Top-7', 'DACH'];
const { objekt, investoren } = $input.first().json;
const treffer = (investoren ?? []).map((inv) => {
  const standort = (inv.regionen ?? []).some((r) => OBERMENGEN.includes(r) || r === objekt.region);
  const teile = String(objekt.assetklasse ?? '').split(' / ');
  const assetklasse = (inv.assetklassen ?? []).some((a) => teile.some((t) => a.includes(t) || t.includes(a)));
  const ticket = inv.ticketMinMio <= objekt.kaufpreisMio && objekt.kaufpreisMio <= inv.ticketMaxMio;
  const voll = standort && assetklasse && ticket;
  return { json: { investorId: inv.id, standort, assetklasse, ticket, voll, hinweis: voll ? null : 'manuell pruefen' } };
});
// Standort ist K.-o. nur fuer den AUTOMATISCHEN Vorschlag – Rest sortiert nach Trefferzahl.
return treffer.sort((a, b) => Number(b.json.voll) - Number(a.json.voll));
